def preco_com_taxa(p, adicional=0):
    base = p * 1.10
    if additional == 5:
        return round(base + 5, 2)
    elif additional == 12:
        return round(base + 12, 2)
    else:
        return round(base, 2)

def total_a(p):
    return preco_com_taxa(p)

def total_b(p):
    return preco_com_taxa(p, adicional=5)

def total_c(p):
    return preco_com_taxa(p, adicional=12)
```

```python
def preco_com_taxa(p, adicional=0):
    # Cálculo unificado: taxa de 10% e adição do valor adicional
    return round((p + adicional) * 1.10, 2)

# Funções originais reescritas usando a função precalculated
def total_a(p):
    return preco_com_taxa(p)

def total_b(p):
    return preco_com_taxa(p, adicional=5)

def total_c(p):
    return preco_com_taxa(p, adicional=12)
```
